mapper.sql:
FROM t_meeting_booking
WHERE is_deleted = 0

    AND room_id = #{query.roomId}


    AND booker_id = #{query.bookerId}


    AND status = #{query.status}


    AND end_time >= #{query.startTime}


    AND start_time <= #{query.endTime}

mapper.select:
SELECT


ORDER BY start_time DESC, id DESC
LIMIT #{offset}, #{size}

SELECT b.id, b.booking_no, b.room_id, b.booker_id, b.meeting_title, b.participant_count,
       b.start_time, b.end_time, b.status, b.remark, b.create_time, b.update_time, b.is_deleted,
       r.room_name, r.location, r.equipment, u.real_name AS booker_name
FROM t_meeting_booking b
INNER JOIN t_meeting_room r ON r.id = b.room_id AND r.is_deleted = 0
LEFT JOIN t_user u ON u.id = b.booker_id AND u.is_deleted = 0
WHERE b.is_deleted = 0
  AND b.start_time < #{query.endTime}
  AND b.end_time > #{query.startTime}

    AND b.room_id = #{query.roomId}



        AND b.status = #{query.status}


        AND b.status != 3


ORDER BY r.id ASC, b.start_time ASC, b.id ASC

SELECT COUNT(1)
FROM t_meeting_booking
WHERE room_id = #{roomId}
  AND status IN (0, 1)
  AND is_deleted = 0
  AND start_time < #{endTime}
  AND end_time > #{startTime}
